pkill -9 qemu-system-riscv64 2>/dev/null || true; make kernel/kernel fs.img && nohup /opt/homebrew/bin/qemu-system-riscv64 -machine virt -bios none -kernel kernel/kernel -m 128M -smp 3 -global virtio-mmio.force-legacy=false -drive file=fs.img,if=none,format=raw,id=x0 -device virtio-blk-device,drive=x0,bus=virtio-mmio-bus.0 -s -S /tmp/qemu-xv6.log 2>&1 & sleep 3 && echo 'QEMU started'